tape( 'the function performs the matrix-matrix operation `C = α*A*A**T + β*C` (column_major, column_major, lower, no-transpose)', function test( t ) {
	var expected;
	var data;
	var out;
	var a;
	var c;

	data = cacclnt;

	a = new Float32Array( data.A );
	c = new Float32Array( data.C );

	expected = new Float32Array( data.C_out );

	out = ssyrk( data.uplo, data.trans, data.N, data.K, data.alpha, a, data.strideA1, data.strideA2, data.offsetA, data.beta, c, data.strideC1, data.strideC2, data.offsetC );
	t.strictEqual( out, c, 'returns expected value' );
	t.deepEqual( out, expected, 'returns expected value' );
	t.end();
});

